/**
 * ToolExecutor Component
 * Modal for executing MCP tools with SMART FORMS - NO JSON REQUIRED!
 */
import { useState, useEffect, useMemo, Component, type ReactNode, type ErrorInfo } from 'react';
import { useExecuteTool } from '@/hooks/useExecuteTool';
import { SmartForm } from './SmartForm';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { ScrollArea } from '@/components/ui/scroll-area';
import { AlertTriangle, Coins, Loader2, CheckCircle2, Sparkles, Search } from 'lucide-react';
import { useDocTypes } from '@/hooks/useDiscovery';
import type { MCPTool } from '@/types';

// ── Error Boundary ──────────────────────────────────────────────────
class ToolErrorBoundary extends Component<
  { children: ReactNode; onReset: () => void },
  { hasError: boolean; error: Error | null }
> {
  constructor(props: { children: ReactNode; onReset: () => void }) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('ToolExecutor error:', error, info);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="rounded-lg border border-destructive/50 p-6 text-center space-y-3">
          <AlertTriangle className="h-8 w-8 text-destructive mx-auto" />
          <p className="font-medium">Something went wrong rendering this tool.</p>
          <p className="text-sm text-muted-foreground">{this.state.error?.message}</p>
          <Button variant="outline" size="sm" onClick={() => {
            this.setState({ hasError: false, error: null });
            this.props.onReset();
          }}>
            Try Again
          </Button>
        </div>
      );
    }
    return this.props.children;
  }
}

// ── Searchable DocType Selector (no cmdk dependency) ────────────────
function DocTypeSelector({
  value,
  onChange,
  doctypes,
  placeholder = 'Search and select a DocType...',
}: {
  value: string;
  onChange: (val: string) => void;
  doctypes: Array<{ name: string; module: string }> | undefined;
  placeholder?: string;
}) {
  const [search, setSearch] = useState('');
  const [isOpen, setIsOpen] = useState(false);

  const filtered = useMemo(() => {
    if (!doctypes) return [];
    if (!search) return doctypes.slice(0, 50); // Show first 50 by default
    const q = search.toLowerCase();
    return doctypes.filter(
      (dt) => dt.name.toLowerCase().includes(q) || dt.module.toLowerCase().includes(q)
    ).slice(0, 50);
  }, [doctypes, search]);

  return (
    <div className="relative">
      <div className="flex gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setIsOpen(true);
            }}
            onFocus={() => setIsOpen(true)}
            placeholder={placeholder}
            className="pl-9"
          />
        </div>
      </div>
      {value && (
        <div className="mt-1.5 flex items-center gap-2">
          <Badge variant="secondary">{value}</Badge>
          <button
            type="button"
            onClick={() => { onChange(''); setSearch(''); }}
            className="text-xs text-muted-foreground hover:text-foreground"
          >
            Clear
          </button>
        </div>
      )}
      {isOpen && filtered.length > 0 && (
        <div className="absolute z-50 mt-1 w-full rounded-md border bg-popover shadow-md max-h-60 overflow-y-auto">
          {filtered.map((dt) => (
            <button
              key={dt.name}
              type="button"
              className="flex w-full items-center justify-between px-3 py-2 text-sm hover:bg-accent hover:text-accent-foreground transition-colors text-left"
              onClick={() => {
                onChange(dt.name);
                setSearch('');
                setIsOpen(false);
              }}
            >
              <span className={value === dt.name ? 'font-medium' : ''}>{dt.name}</span>
              <Badge variant="outline" className="ml-2 text-xs shrink-0">{dt.module}</Badge>
            </button>
          ))}
        </div>
      )}
      {isOpen && search && filtered.length === 0 && (
        <div className="absolute z-50 mt-1 w-full rounded-md border bg-popover shadow-md p-4 text-center text-sm text-muted-foreground">
          No DocType found matching "{search}"
        </div>
      )}
      {/* Click-away handler */}
      {isOpen && (
        <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
      )}
    </div>
  );
}

// ── Main ToolExecutor ───────────────────────────────────────────────
interface ToolExecutorProps {
  tool: MCPTool;
  open: boolean;
  onClose: () => void;
  initialParams?: Record<string, any>;
}

export function ToolExecutor({ tool, open, onClose, initialParams = {} }: ToolExecutorProps) {
  const [params, setParams] = useState<Record<string, any>>(initialParams);
  const [result, setResult] = useState<any>(null);
  const [showSmartForm, setShowSmartForm] = useState(false);
  const executeMutation = useExecuteTool();
  const { data: doctypes } = useDocTypes();

  useEffect(() => {
    setParams(initialParams);
  }, [initialParams]);

  const handleExecute = () => {
    executeMutation.mutate(
      { toolName: tool.name, params },
      {
        onSuccess: (data) => {
          setResult(data.result);
        },
      }
    );
  };

  const handleClose = () => {
    setParams({});
    setResult(null);
    setShowSmartForm(false);
    executeMutation.reset();
    onClose();
  };

  const updateParam = (key: string, value: any) => {
    setParams((prev) => ({ ...prev, [key]: value }));
  };

  const handleSmartFormChange = (values: Record<string, any>) => {
    setParams(prev => ({ ...prev, data: values }));
  };

  // Check if we should show smart form
  const needsDocTypeSelection = (tool.name === 'create_document' || tool.name === 'update_document') && !showSmartForm;
  const canUseSmartForm = (tool.name === 'create_document' || tool.name === 'update_document') && params.doctype;

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-6xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {canUseSmartForm && <Sparkles className="h-5 w-5 text-primary" />}
            {tool.title}
            {tool.destructive && <AlertTriangle className="h-5 w-5 text-red-600" />}
          </DialogTitle>
          <DialogDescription>{tool.description}</DialogDescription>
          <div className="flex gap-2 pt-2">
            <Badge variant="outline">{tool.category}</Badge>
            <Badge variant="secondary" className="gap-1">
              <Coins className="h-3 w-3" />
              {tool.base_cost} credits
            </Badge>
          </div>
        </DialogHeader>

        {tool.destructive && !result && (
          <Alert variant="destructive">
            <AlertTriangle className="h-4 w-4" />
            <AlertDescription>
              This is a destructive operation. Please proceed with caution.
            </AlertDescription>
          </Alert>
        )}

        <ToolErrorBoundary onReset={handleClose}>
          <ScrollArea className="max-h-[500px]">
            {result ? (
              <div className="space-y-4 p-1">
                <div className="flex items-center gap-2 text-green-600">
                  <CheckCircle2 className="h-5 w-5" />
                  <span className="font-medium">Execution Successful</span>
                </div>
                <div className="rounded-lg bg-muted p-4">
                  <pre className="text-xs overflow-x-auto">
                    {JSON.stringify(result, null, 2)}
                  </pre>
                </div>
              </div>
            ) : (
              <div className="space-y-6 p-1">
                {/* DocType Selection for Create/Update */}
                {needsDocTypeSelection && (
                  <div className="space-y-2">
                    <Label>
                      Select Document Type
                      <span className="ml-1 text-red-600">*</span>
                    </Label>
                    <DocTypeSelector
                      value={params.doctype || ''}
                      onChange={(val) => {
                        updateParam('doctype', val);
                        if (val) setShowSmartForm(true);
                      }}
                      doctypes={doctypes}
                      placeholder="Search DocTypes to create..."
                    />
                    <p className="text-xs text-muted-foreground">
                      Select a document type to see user-friendly form fields
                    </p>
                  </div>
                )}

                {/* Smart Form for Create/Update */}
                {canUseSmartForm && showSmartForm && (
                  <div className="space-y-4">
                    <div className="flex items-center gap-2 rounded-lg bg-primary/10 p-3">
                      <Sparkles className="h-4 w-4 text-primary" />
                      <p className="text-sm font-medium">
                        Smart Form for {params.doctype}
                      </p>
                    </div>
                    <SmartForm
                      doctype={params.doctype}
                      initialValues={params.data || {}}
                      onChange={handleSmartFormChange}
                    />
                  </div>
                )}

                {/* Simple Fields for Other Tools */}
                {!needsDocTypeSelection && !canUseSmartForm && (
                  <div className="space-y-4">
                    {/* DocType field for other tools */}
                    {(tool.name.includes('document') || tool.name.includes('get_list') ||
                      tool.name.includes('search') || tool.name.includes('dashboard')) && (
                      <div className="space-y-2">
                        <Label>
                          Document Type
                          <span className="ml-1 text-red-600">*</span>
                        </Label>
                        <DocTypeSelector
                          value={params.doctype || ''}
                          onChange={(val) => updateParam('doctype', val)}
                          doctypes={doctypes}
                        />
                      </div>
                    )}

                    {/* Name field */}
                    {(tool.name === 'get_document' || tool.name === 'update_document' || tool.name === 'delete_document') && (
                      <div className="space-y-2">
                        <Label htmlFor="name">
                          Document ID / Name
                          <span className="ml-1 text-red-600">*</span>
                        </Label>
                        <Input
                          id="name"
                          value={params.name || ''}
                          onChange={(e) => updateParam('name', e.target.value)}
                          placeholder="Enter document name or ID"
                        />
                      </div>
                    )}

                    {/* Search text */}
                    {tool.name === 'search_documents' && (
                      <div className="space-y-2">
                        <Label htmlFor="search_text">
                          Search For
                          <span className="ml-1 text-red-600">*</span>
                        </Label>
                        <Input
                          id="search_text"
                          value={params.search_text || ''}
                          onChange={(e) => updateParam('search_text', e.target.value)}
                          placeholder="What are you looking for?"
                        />
                      </div>
                    )}

                    {/* Limit field */}
                    {(tool.name === 'get_list' || tool.name === 'search_documents' || tool.name === 'export_data') && (
                      <div className="space-y-2">
                        <Label htmlFor="limit">Maximum Results</Label>
                        <Input
                          id="limit"
                          type="number"
                          value={params.limit || 20}
                          onChange={(e) => updateParam('limit', parseInt(e.target.value))}
                          min="1"
                          max="100"
                        />
                      </div>
                    )}

                    {/* Report name */}
                    {tool.name === 'execute_report' && (
                      <div className="space-y-2">
                        <Label htmlFor="report_name">
                          Report Name
                          <span className="ml-1 text-red-600">*</span>
                        </Label>
                        <Input
                          id="report_name"
                          value={params.report_name || ''}
                          onChange={(e) => updateParam('report_name', e.target.value)}
                          placeholder="Enter report name"
                        />
                      </div>
                    )}

                    {/* Bulk update fields */}
                    {tool.name === 'bulk_update' && (
                      <div className="space-y-2">
                        <Label htmlFor="filters">
                          Filters (JSON)
                        </Label>
                        <Input
                          id="filters"
                          value={params.filters || ''}
                          onChange={(e) => updateParam('filters', e.target.value)}
                          placeholder='e.g., {"status": "Open"}'
                        />
                        <Label htmlFor="update_data">
                          Update Data (JSON)
                        </Label>
                        <Input
                          id="update_data"
                          value={params.update_data || ''}
                          onChange={(e) => updateParam('update_data', e.target.value)}
                          placeholder='e.g., {"status": "Closed"}'
                        />
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </ScrollArea>
        </ToolErrorBoundary>

        <DialogFooter>
          {result ? (
            <Button onClick={handleClose}>Close</Button>
          ) : (
            <>
              <Button variant="outline" onClick={handleClose}>
                Cancel
              </Button>
              <Button
                onClick={handleExecute}
                disabled={executeMutation.isPending || (needsDocTypeSelection && !params.doctype)}
                variant={tool.destructive ? 'destructive' : 'default'}
              >
                {executeMutation.isPending ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Executing...
                  </>
                ) : (
                  <>Execute</>
                )}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
